import { defineExperience, startExperience } from "@signal-lab/experience-sdk";
import { DreamRoomScene } from "./scene";
import { directDream } from "./director";

const OPENING_URI = "/creative-assets/dream-room-awakening-v1.png";
const MEMORY_URI = "/creative-assets/dream-memory-fragments-v1.png";
const FINAL_URI = "/creative-assets/dream-night-record-v1.png";

let scene: DreamRoomScene | null = null;
let root: HTMLElement | null = null;
let environmentLayers: HTMLElement[] = [];

const clamp01 = (value: number): number => Math.min(1, Math.max(0, value));
const smooth = (start: number, end: number, value: number): number => {
  const t = clamp01((value - start) / (end - start));
  return t * t * (3 - 2 * t);
};

function environmentOpacity(progress: number): [number, number, number] {
  const p = clamp01(progress);
  const memoryBlend = smooth(0.22, 0.38, p);
  const finalBlend = smooth(0.62, 0.78, p);
  const overlapCurve = 0.4;

  return [
    Math.pow(1 - memoryBlend, overlapCurve),
    Math.pow(memoryBlend, overlapCurve) * Math.pow(1 - finalBlend, overlapCurve),
    Math.pow(finalBlend, overlapCurve)
  ];
}

function buildPage(container: HTMLElement): HTMLElement {
  const page = document.createElement("main");
  page.className = "dream-page";
  page.innerHTML = `
    <div class="dream-environments" aria-hidden="true">
      <div class="dream-environment dream-environment--opening"></div>
      <div class="dream-environment dream-environment--memory"></div>
      <div class="dream-environment dream-environment--final"></div>
    </div>
    <div class="dream-vignette" aria-hidden="true"></div>
    <section class="dream-hero" aria-labelledby="dream-title">
      <div class="dream-copy dream-copy--opening">
        <p class="dream-kicker">梦境记录</p>
        <h1 id="dream-title">醒来以后，<br>先别急着起身。</h1>
        <p class="dream-lede">有些梦只在清晨停留几分钟。慢一点，让房间替你记住它消失前的形状。</p>
        <a class="dream-scroll" href="#memory">沿着记忆往里走 <span aria-hidden="true">↓</span></a>
      </div>
    </section>
    <section id="memory" class="dream-passage" aria-labelledby="memory-title">
      <div class="dream-copy dream-copy--memory">
        <p class="dream-kicker">未整理的片段</p>
        <h2 id="memory-title">窗纱、脚步，<br>一句没说完的话。</h2>
        <p>不必立刻解释。先把声音、光线和身体的感觉留在原处，它们会慢慢连成一条路。</p>
      </div>
    </section>
    <section class="dream-resolution" aria-labelledby="record-title">
      <div class="dream-copy dream-copy--final">
        <p class="dream-kicker">留给清醒的你</p>
        <h2 id="record-title">记录今晚的梦</h2>
        <p>从一个画面开始。无需完整，也无需合理。</p>
        <button class="dream-cta" type="button" aria-label="开始记录今晚的梦">开始记录 <span aria-hidden="true">→</span></button>
        <p class="dream-note">文字、声音，或只写下一个颜色。</p>
      </div>
    </section>`;

  environmentLayers = Array.from(
    page.querySelectorAll<HTMLElement>(".dream-environment")
  );
  environmentLayers[0]?.style.setProperty("background-image", `url("${OPENING_URI}")`);
  environmentLayers[1]?.style.setProperty("background-image", `url("${MEMORY_URI}")`);
  environmentLayers[2]?.style.setProperty("background-image", `url("${FINAL_URI}")`);
  container.appendChild(page);
  return page;
}

startExperience(defineExperience({
  mount(context) {
    root = buildPage(context.container);
    try {
      scene = new DreamRoomScene(
        context.canvas,
        context.viewport,
        context.quality,
        context.reducedMotion
      );
    } catch {
      scene = null;
      root.classList.add("dream-page--fallback");
    }
  },
  update(frame) {
    if (!root) return;
    const state = directDream(
      frame.progress,
      frame.pointer,
      frame.elapsed,
      frame.reducedMotion
    );
    const opacities = environmentOpacity(state.progress);

    scene?.render(state, frame.delta);
    for (let index = 0; index < environmentLayers.length; index += 1) {
      environmentLayers[index].style.opacity = opacities[index].toFixed(3);
    }
    root.classList.toggle("dream-page--final-visible", state.progress >= 0.78);
    root.style.setProperty("--opening-copy", state.openingCopy.toFixed(3));
    root.style.setProperty("--memory-copy", state.memoryCopy.toFixed(3));
    root.style.setProperty("--final-copy", state.finalCopy.toFixed(3));
    root.style.setProperty("--veil", state.veil.toFixed(3));
  },
  resize(viewport) {
    scene?.resize(viewport);
  },
  dispose() {
    scene?.dispose();
    scene = null;
    environmentLayers = [];
    root?.remove();
    root = null;
  }
}));

export interface DreamState {
  progress: number;
  opening: number;
  passage: number;
  resolution: number;
  openingCopy: number;
  memoryCopy: number;
  finalCopy: number;
  focus: number;
  corridorDepth: number;
  fragmentSpread: number;
  finalClarity: number;
  veil: number;
  cameraX: number;
  cameraY: number;
  breath: number;
}

const clamp01 = (value: number): number => Math.min(1, Math.max(0, value));
const smooth = (a: number, b: number, value: number): number => {
  const t = clamp01((value - a) / (b - a));
  return t * t * (3 - 2 * t);
};

export function directDream(
  progress: number,
  pointer: { x: number; y: number },
  elapsed: number,
  reducedMotion: boolean
): DreamState {
  const p = clamp01(progress);
  const memoryIn = smooth(0.23, 0.42, p);
  const finalIn = smooth(0.68, 0.9, p);
  const memoryOut = smooth(0.72, 0.94, p);
  const opening = 1 - smooth(0.3, 0.48, p);
  const passage = memoryIn * (1 - memoryOut);
  const resolution = finalIn;
  const pointerWeight = reducedMotion ? 0 : 0.038;
  const breath = reducedMotion ? 0 : Math.sin(elapsed * 0.34) * 0.006;

  return {
    progress: p,
    opening,
    passage,
    resolution,
    openingCopy: 1 - smooth(0.12, 0.3, p),
    memoryCopy: smooth(0.3, 0.46, p) * (1 - smooth(0.62, 0.76, p)),
    finalCopy: smooth(0.78, 0.92, p),
    focus: smooth(0.04, 0.22, p),
    corridorDepth: memoryIn * (1 - finalIn * 0.62),
    fragmentSpread: Math.sin(memoryIn * Math.PI) * (1 - finalIn * 0.48),
    finalClarity: resolution,
    veil: 0.16 - passage * 0.05 - resolution * 0.03,
    cameraX: pointer.x * pointerWeight * (0.55 + passage * 0.45),
    cameraY: pointer.y * pointerWeight * 0.36 + breath,
    breath
  };
}

import * as THREE from "three";
import type { DreamState } from "./director";

interface Viewport {
  width: number;
  height: number;
  dpr: number;
}

type Quality = "low" | "balanced" | "high";

const MEMORY_URI = "/creative-assets/dream-memory-fragments-v1.png";

const vertexShader = `
  varying vec2 vUv;

  void main() {
    vUv = uv;
    gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
  }
`;

const fragmentShader = `
  uniform sampler2D uMap;
  uniform float uHasMap;
  uniform float uOpacity;
  uniform float uImageAspect;
  uniform float uViewAspect;
  uniform float uBreath;
  uniform vec2 uParallax;
  varying vec2 vUv;

  vec2 coverUv(vec2 uv) {
    float ratio = uViewAspect / max(uImageAspect, 0.001);
    if (ratio > 1.0) {
      uv.y = (uv.y - 0.5) / ratio + 0.5;
    } else {
      uv.x = (uv.x - 0.5) * ratio + 0.5;
    }
    return uv;
  }

  void main() {
    vec2 breathingUv = (vUv - 0.5) * (1.0 + uBreath) + 0.5;
    vec2 uv = coverUv(breathingUv) + uParallax;
    vec2 px = vec2(0.0025);

    vec3 image = texture2D(uMap, uv).rgb * 0.52;
    image += texture2D(uMap, uv + vec2(px.x, 0.0)).rgb * 0.12;
    image += texture2D(uMap, uv - vec2(px.x, 0.0)).rgb * 0.12;
    image += texture2D(uMap, uv + vec2(0.0, px.y)).rgb * 0.12;
    image += texture2D(uMap, uv - vec2(0.0, px.y)).rgb * 0.12;

    float luminance = dot(image, vec3(0.2126, 0.7152, 0.0722));
    float luminanceMask = smoothstep(0.16, 0.72, luminance);
    float feather =
      smoothstep(0.0, 0.18, vUv.x) *
      smoothstep(0.0, 0.18, vUv.y) *
      smoothstep(0.0, 0.18, 1.0 - vUv.x) *
      smoothstep(0.0, 0.18, 1.0 - vUv.y);
    float alpha = uOpacity * uHasMap * luminanceMask * feather;

    gl_FragColor = vec4(image, alpha);
  }
`;

export class DreamRoomScene {
  private readonly renderer: THREE.WebGLRenderer;
  private readonly scene = new THREE.Scene();
  private readonly camera = new THREE.PerspectiveCamera(38, 1, 0.1, 30);
  private readonly geometry = new THREE.PlaneGeometry(2, 2, 1, 1);
  private readonly material: THREE.ShaderMaterial;
  private readonly echo: THREE.Mesh<THREE.PlaneGeometry, THREE.ShaderMaterial>;
  private readonly fallbackTexture: THREE.DataTexture;
  private memoryTexture: THREE.Texture | null = null;
  private readonly quality: Quality;
  private readonly reducedMotion: boolean;
  private viewport: Viewport;
  private disposed = false;

  constructor(
    canvas: HTMLCanvasElement,
    viewport: Viewport,
    quality: Quality,
    reducedMotion: boolean
  ) {
    this.viewport = viewport;
    this.quality = quality;
    this.reducedMotion = reducedMotion;
    this.renderer = new THREE.WebGLRenderer({
      canvas,
      antialias: quality !== "low",
      alpha: true,
      premultipliedAlpha: false,
      powerPreference: quality === "high" ? "high-performance" : "default"
    });
    this.renderer.setClearColor(0x000000, 0);
    this.renderer.outputColorSpace = THREE.SRGBColorSpace;
    this.renderer.toneMapping = THREE.ACESFilmicToneMapping;
    this.renderer.toneMappingExposure = 0.9;

    this.fallbackTexture = new THREE.DataTexture(
      new Uint8Array([0, 0, 0, 0]),
      1,
      1,
      THREE.RGBAFormat
    );
    this.fallbackTexture.needsUpdate = true;

    this.material = new THREE.ShaderMaterial({
      vertexShader,
      fragmentShader,
      transparent: true,
      depthTest: false,
      depthWrite: false,
      blending: THREE.NormalBlending,
      uniforms: {
        uMap: { value: this.fallbackTexture },
        uHasMap: { value: 0 },
        uOpacity: { value: 0 },
        uImageAspect: { value: 16 / 9 },
        uViewAspect: {
          value: viewport.width / Math.max(1, viewport.height)
        },
        uBreath: { value: 0 },
        uParallax: { value: new THREE.Vector2() }
      }
    });

    this.echo = new THREE.Mesh(this.geometry, this.material);
    this.echo.frustumCulled = false;
    this.scene.add(this.echo);

    this.camera.position.set(0, 0, 3.5);
    this.loadMemoryTexture();
    this.resize(viewport);
  }

  private loadMemoryTexture(): void {
    new THREE.TextureLoader().load(
      MEMORY_URI,
      (texture: THREE.Texture) => {
        if (this.disposed) {
          texture.dispose();
          return;
        }

        texture.colorSpace = THREE.SRGBColorSpace;
        texture.minFilter = THREE.LinearFilter;
        texture.magFilter = THREE.LinearFilter;
        texture.generateMipmaps = false;
        this.memoryTexture = texture;

        const image = texture.image as { width?: number; height?: number };
        const aspect = image.width && image.height
          ? image.width / image.height
          : 16 / 9;

        this.material.uniforms.uMap.value = texture;
        this.material.uniforms.uHasMap.value = 1;
        this.material.uniforms.uImageAspect.value = aspect;
      }
    );
  }

  resize(viewport: Viewport): void {
    this.viewport = viewport;
    this.renderer.setPixelRatio(
      Math.min(viewport.dpr, this.quality === "high" ? 2 : 1.35)
    );
    this.renderer.setSize(viewport.width, viewport.height, false);
    this.camera.aspect = viewport.width / Math.max(1, viewport.height);
    this.camera.updateProjectionMatrix();

    const viewHeight =
      2 *
      Math.tan(THREE.MathUtils.degToRad(this.camera.fov * 0.5)) *
      this.camera.position.z;
    const viewWidth = viewHeight * this.camera.aspect;
    this.echo.scale.set(viewWidth * 0.5, viewHeight * 0.5, 1);
    this.material.uniforms.uViewAspect.value = this.camera.aspect;
  }

  render(state: DreamState, _delta: number): void {
    this.material.uniforms.uOpacity.value = Math.min(0.08, state.passage * 0.08);
    this.material.uniforms.uBreath.value = this.reducedMotion
      ? 0
      : state.breath * 0.35;
    this.material.uniforms.uParallax.value.set(
      this.reducedMotion ? 0 : state.cameraX * 0.03,
      this.reducedMotion ? 0 : state.cameraY * 0.02
    );

    this.renderer.render(this.scene, this.camera);
  }

  dispose(): void {
    this.disposed = true;
    this.scene.remove(this.echo);
    this.material.dispose();
    this.geometry.dispose();
    this.memoryTexture?.dispose();
    this.memoryTexture = null;
    this.fallbackTexture.dispose();
    this.scene.clear();
    this.renderer.dispose();
  }
}
